D=[dict(zip(['id','line','model','provider','cost','source','sha256','dest','alt','rights','note'],x)) for x in K]
rows={r['image_file']:r for r in map(json.loads,(EX/'provenance.jsonl').read_text().splitlines())}
def sha(b): return hashlib.sha256(b).hexdigest()
for k in D:
    src=(EX/'images'/k['source']).read_bytes(); r=rows[k['source']]
    assert sha(src)==k['sha256']==r['image_sha256']; assert r['model']==k['model'] and r['provider_tag']==k['provider'] and r['error'] is None
    dst=OUT/'assets/chad'/k['dest']; dst.parent.mkdir(parents=True,exist_ok=True); dst.write_bytes(src)
def block(k):
    return f'<p align="center">\n  <img src="assets/chad/{k["dest"]}" alt="{k["alt"]}" width="620">\n</p>\n\n<p align="center"><em>annoned by <code>{k["model"]}</code> · <a href="assets/chad/PROVENANCE.md#{k["id"]}">receipt</a></em></p>\n\n'
def ins(t,a,b):
    assert t.count(a)==1,(a,t.count(a)); return t.replace(a,a+b,1)
