ph=PH.read_text()
for a,i in [('The point is to find out what is actually true.\n\n','truth-not-winning'),('A test is better than an assurance.\n\n','test-not-assurance'),('If the world proves you wrong, change your mind.\n\n','change-mind'),('Chad philosophy does not protect ideas from reality.\n\n','ideas-meet-reality'),('Chad philosophy therefore prefers **recoverable progress** over heroic overextension.\n\n','recoverable-progress'),('## Capability is not permission\n\n','capability-not-permission'),('> **No high-consequence actuator without an independently authorized gate in its causal past that can still say no.**\n\n','authorized-gate'),('> **Do not put the brake on the same failure path as the engine.**\n\n','brake-engine-path'),('Mechanical checks should become cheap wherever we can make them cheap. Provenance should become cheap. Reproducibility should become cheap. Tests should become cheap.\n\n','mechanical-checks'),('So when testing an idea, use the strongest reasonable criticism you can find.\n\n','strongest-criticism'),('Rest, delegation, and asking for help are not failures of seriousness. They are ways of preserving judgment for the next branch point.\n\n','rest-delegation')]: ph=ins(ph,a,block(M[i]))
